			/*
			 * 사용자 정의 컨트롤에서 clear 이벤트 발생 시 호출.
			 * 초기화 버튼 클릭시 이벤트
			 */
			function onComBtnSearch2Clear(e){
			    var comBtnSearch2 = e.control;
			    
			    var dmSearch = app.lookup("dmSearch");
			    var dsCyberDeptList = app.lookup("dsOgdpInstList");
			    var vcDeptCombo = app.lookup("cmb3");
			    
			    var findDeptList = dsCyberDeptList.findAllRow("DEPT_CD == " + userDeptNo);
			    
			    if (findDeptList.length > 0) {
			        dmSearch.setValue("DEPT_CD", userDeptNo);
			    } else {
			        vcDeptCombo.selectItem(0);
			    }
			    
			    dmSearch.setValue("RLVT_YR", moment().format("YYYY"));
			    
			    util.Control.redraw(app, "grpSearch");
			}

